entries[218106] = { ["name"] = "Stillstone Frog Trap", ["text"] = "Binds when picked up\nUse: Throw a Frog Trap on the ground that will do 20 physical damage when an enemy walks on it, and stuns them for 6 sec.\n\nUsable at Stillstone Pond and nearby areas. (10 Sec Cooldown)" }
entries[218107] = { ["name"] = "Sparkbug Jar", ["text"] = "Binds when picked up\nUnique (20)\nUse: Shaking the jar causes the sparkbugs inside to glow faintly providing a dim light.\n\nWith this light you can locate hidden items in Stillstone Pond and the nearby keyflame areas. (15 Sec Cooldown)\n\"The small luminescent bugs inside provide a fanciful colorful light.\"" }
entries[218108] = { ["name"] = "Dark Pact", ["text"] = "Cogwheel Gem\nBinds when picked up\nUnique\nEquip: Learn the following spell.\n\nDark Pact\nSacrifices 20% of your current health to shield you for 200% of the sacrificed health for 20 sec. Usable while suffering from control impairing effects.\nRequires level 10 to 80 ( 80)\n\"Fits in a Cogwheel socket.\"" }
entries[218109] = { ["name"] = "Death's Advance", ["text"] = "Cogwheel Gem\nBinds when picked up\nUnique\nEquip: Learn the following spell.\n\nDeath's Advance\nFor 10 sec, your movement speed is increased by 35%, you cannot be slowed below 100% of normal speed, and you are immune to forced movement effects and knockbacks.\nRequires level 10 to 80 ( 80)\n\"Fits in a Cogwheel socket.\"" }
entries[218110] = { ["name"] = "Soulshape", ["text"] = "Cogwheel Gem\nBinds when picked up\nUnique\nEquip: Learn the following spell.\n\nSoulshape\nTurn into a Vulpin for 12 sec, teleporting 15 yds forward and increasing your movement speed by 50%. You may reactivate Soulshape every few sec to teleport again.\nRequires level 10 to 80 ( 80)\n\"Fits in a Cogwheel socket.\"" }
entries[218111] = { ["name"] = "Reins of the Amber Pterrordax", ["text"] = "Remix: Pandaria\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The Pterrordax could and would eat you in seconds. Are you sure sitting on its back is a good idea?\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[218112] = { ["name"] = "Colorful Beach Chair", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Set up a colorful beach chair. (5 Min Cooldown)\n\"After taking a dip to beat the summer heat, rest assured on the stylish comfort of this perfect blend of warm sunsets and relaxing rainbow hues.\"" }
