entries[218125] = { ["name"] = "Reactive Webbed Escutcheon", ["text"] = "Binds when picked up\nUnique-Equipped\nOff Hand Shield\n2442 Armor\n+128 Strength\n+394 Intellect\n+ 193 Bonus Armor\nDurability 120 / 120\nEquip: Taking magic damage has a chance for the webbing to react and adapt, spinning Warding Threads around you for 30 sec. While active, Warding Threads absorb all damage you would take from that source's spell school, up to 81103 . (2 min Cooldown) (2m cooldown)\nSell Price:" }
entries[218126] = { ["name"] = "Befouler's Syringe", ["text"] = "Binds when picked up\nUnique-Equipped\nTwo-Hand Polearm\n487 - 905 Damage Speed 3.60\n(193.3 damage per second)\n+416 Stamina\n+ 478 Haste\nDurability 120 / 120\nEquip: Your melee attacks and abilities have a chance to befoul the blood of your enemy dealing [source value] Nature damage over 10 sec. Additional injections overlap.\n\nIf a target dies while afflicted with your Befouled Blood, siphon the remaining poison back into the blade granting your next melee abilities ( 1 * 8083 ) additional Nature damage.\nSell Price:", ["unresolvedValues"] = true }
