entries[219006] = { ["name"] = "Roaring Anglerseeker Lure", ["text"] = "Use: Coat your hook in Anglerseeker bait, guaranteeing the catch from any Fishing Pool in The Ringing Deeps or Hallowfall.\n\nThis bait lasts 30 min and stacks up to 50 times.\nSell Price:" }
entries[219007] = { ["name"] = "Elusive Creature Lure", ["text"] = "Binds when picked up\nUse: Place the bait, luring an elusive creature after a small amount of time. Who knows what might show up?\n\nThe cooldown of Elusive Creature Bait is lowered by skinning creatures in Khaz Algar.\n\nOnly usable outdoors in Khaz Algar.\nRequires Khaz Algar Skinning (1)\n\"An enticing bait to draw elusive creatures out of hiding.\"\nSell Price:" }
entries[219008] = { ["name"] = "Supreme Beast Lure", ["text"] = "Binds when picked up\nUse: Place the bait, luring a supreme elusive creature out of hiding.\n\nOnly usable in the Rumbling Wastes, located in the Ringing Deeps.\nRequires Khaz Algar Skinning (1)\n\"An exquisite lure designed and crafted to precise specifications for which to draw out a powerful beast.\"\nSell Price:" }
entries[219009] = { ["name"] = "Crystalline Creature Lure", ["text"] = "Binds when picked up\nUse: Place the bait, luring an elusive creature after a small amount of time. Who knows what might show up?\n\nThe cooldown of Elusive Creature Bait is lowered by skinning creatures in Khaz Algar.\n\nOnly usable outdoors in Khaz Algar.\n\"An enticing bait to draw elusive creatures out of hiding. Infused with crystalline power.\"\nSell Price:" }
entries[219010] = { ["name"] = "Writhing Creature Lure", ["text"] = "Binds when picked up\nUse: Place the bait, luring an elusive creature after a small amount of time. Who knows what might show up?\n\nThe cooldown of Elusive Creature Bait is lowered by skinning creatures in Khaz Algar.\n\nOnly usable outdoors in Khaz Algar.\n\"An enticing bait to draw elusive creatures out of hiding. Infused with essence that weeps with malevolent energy.\"\nSell Price:" }
entries[219011] = { ["name"] = "Sporefused Creature Lure", ["text"] = "Binds when picked up\nUse: Place the bait, luring an elusive creature after a small amount of time. Who knows what might show up?\n\nThe cooldown of Elusive Creature Bait is lowered by skinning creatures in Khaz Algar.\n\nOnly usable outdoors in Khaz Algar.\n\"An enticing bait to draw elusive creatures out of hiding. Infused with magical spores.\"\nSell Price:" }
entries[219013] = { ["name"] = "Superb Beast Fang", ["text"] = "Crafting Reagent\n\"A mighty fang obtained from a particularly powerful elusive creature on Khaz Algar by skinners. Can be bought and sold on the Auction House.\"\nSell Price:" }
entries[219014] = { ["name"] = "Vengeful Fire Spirit", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 493 Critical Strike\nEquip: Your ranged attacks have a chance to send a vengeful flame towards your target, dealing ( 1 * 19916 ) Fire damage when it reaches them.\n\nThe spirit grows as it travels towards the target, dealing up to 100% additional Fire damage.\nSell Price:" }
entries[219015] = { ["name"] = "Gem of Ausgazur", ["text"] = "Quest Item\n\"Sparkling gently in the light, this gem looks perfect for gazing at for all eternity.\"" }
entries[219016] = { ["name"] = "Coated Steel Tips", ["text"] = "Quest Item" }
entries[219017] = { ["name"] = "Silver Armor Clasps", ["text"] = "Quest Item" }
entries[219018] = { ["name"] = "Esteemed Earthen Emblem", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+389 [Agility or Strength or Intellect]\nEquip: Your spells and abilities have a chance to embolden those around you, granting 924 Versatility split between you and nearby allies.\n\nVersatility is increased for each ally affected, up to 5 allies.\nSell Price:" }
entries[219019] = { ["name"] = "Beast Lure Scent", ["text"] = "Binds when picked up\nUse: Open the bottle, letting out a scent that immediately lures all unoccupied, skinnable beasts within 60 yards to you.\n\nOnly usable outdoors in Khaz Algar. (5 Min Cooldown)\nRequires Khaz Algar Skinning (1)\nSell Price:" }
