entries[219283] = { ["name"] = "Obsidian Iris", ["text"] = "Binds when picked up\nUnique\n\"Tough as the flight they're named for, these pitch black flowers thrive in rugged environments.\"" }
entries[219284] = { ["name"] = "Explosive Sticks", ["text"] = "Quest Item\nUse: Stuns all enemies within 5 yards of the impact, rendering them unable to move or attack for 2 sec.\nInflicts 4 Fire damage to enemies within 5 yards of the impact. (5 Sec Cooldown)\n\"These explosives are good for two things: Collapse kobold tunnels.\"" }
entries[219285] = { ["name"] = "Azure Lily", ["text"] = "Binds when picked up\nUnique\n\"The very petals of this bloom crackle with arcane energy. It is said their buds will not flower unless in the presence of large amounts of magic.\"" }
entries[219286] = { ["name"] = "Puntable Globe Yeti", ["text"] = "Binds when picked up\n\"Learn how to summon puntable Globe Yetis.\"" }
entries[219287] = { ["name"] = "Time-Touched Daisy", ["text"] = "Binds when picked up\nUnique\n\"Covered in a fine bronze dust, these daisies glisten and glitter in the midday sun.\"" }
entries[219288] = { ["name"] = "Viridian Bloom", ["text"] = "Binds when picked up\nUnique\n\"The petals of this flower are cool to the touch, as though they were just plucked from a deep, dark forest.\"" }
entries[219289] = { ["name"] = "Puntable Tiny Snowman", ["text"] = "Binds when picked up\n\"Learn how to summon puntable Tiny Snowmen.\"" }
entries[219290] = { ["name"] = "Ruby Blossom", ["text"] = "Binds when picked up\nUnique\n\"Warm to the touch and thrumming with life, these flowers are absolutely covered in pollen. Great for bees, not noses.\"" }
entries[219291] = { ["name"] = "Puntable Baby Greench", ["text"] = "Binds when picked up\n\"Learn how to summon puntable Baby Greenches.\"" }
entries[219292] = { ["name"] = "Perplexing Contraband", ["text"] = "Quest Item\nUnique (5)\n\"Samophlange Parts - Do Not Shake.\"" }
entries[219293] = { ["name"] = "Sureki Intelligence", ["text"] = "Quest Item\nUnique (4)\n\"An inscrutable array of acrid scents emanates from this seemingly blank parchment.\"" }
entries[219294] = { ["name"] = "Charged Stormrook Plume", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 Agility\nUse: Hold out the feather for [1.0][1] sec to strike with the power of the storm, crashing down on the target location and inflicting ( 1 * 124864 ) Nature damage split between nearby enemies. (1 Min, 30 Sec Cooldown)\nComplete all Mythic+ dungeons within the time limit at keystone level 12 during The War Within Season 2.\nSell Price:" }
entries[219295] = { ["name"] = "Sigil of Algari Concordance", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 [Agility or Strength or Intellect]\nEquip: Your abilities have a chance to call an earthen ally to your aid, supporting you in combat. (15s cooldown)\nComplete all Mythic+ dungeons within the time limit at keystone level 12 during The War Within Season 2.\nSell Price:" }
entries[219296] = { ["name"] = "Entropic Skardyn Core", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 604 Critical Strike\nEquip: Your spells have a chance to destabilize the void energy, releasing a corrupted fragment. Retrieving a fragment briefly infuses you with its power, increasing your Intellect by 1421 for 15 sec.\nComplete all Mythic+ dungeons within the time limit at keystone level 12 during The War Within Season 2.\nSell Price:" }
entries[219297] = { ["name"] = "Cinderbrew Stein", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\nEquip: Occasionally share a drink with allies who assist you in combat, granting them 700 of their primary stat for 15 sec and absorbing 19079 damage. You take a sip as well, granting 377 Primary Stat and absorbing 97936 damage.\n\nWhen you fall below 50% health, you take an emergency sip. This may only occur once every 1 min.\n\nValid only for tank specializations.\nComplete all Mythic+ dungeons within the time limit at keystone level 12 during The War Within Season 2.\n\"Watered down for consumption by lesser mortals.\"\nSell Price:" }
entries[219298] = { ["name"] = "Ravenous Honey Buzzer", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 [Agility or Strength]\nUse: Call in a ravenous ally and ride off into the sunset (or [source value] yds, whichever is closest), inflicting ( 1 * 149371 ) Fire damage split between all enemies you ride through. (1 Min, 30 Sec Cooldown)\nComplete all Mythic+ dungeons within the time limit at keystone level 12 during The War Within Season 2.\nSell Price:", ["unresolvedValues"] = true }
entries[219299] = { ["name"] = "Synergistic Brewterializer", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 Intellect\nEquip: Your spells have a chance to charge the device and request a Backfill Barrel near your target's location. Damaging the barrel causes it to explode, inflicting ( 1 * 84121 ) Fire damage split between nearby enemies.\nComplete all Mythic+ dungeons within the time limit at keystone level 12 during The War Within Season 2.\nSell Price:" }
